<parameter name="path">ErrorBoundary.tsx</parameter>
<parameter name="content">import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary] Caught render error:", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
    });
    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.reset);

    return <DefaultFallback error={error} reset={this.reset} />;
  }
}

function DefaultFallback({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.heading}>Something went wrong</h2>
      <p style={styles.message}>{error.message}</p>
      {error.stack && (
        <details style={styles.details}>
          <summary style={styles.summary}>Stack trace</summary>
          <pre style={styles.stack}>{error.stack}</pre>
        </details>
      )}
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    margin: "1rem",
    border: "1px solid #f5c6cb",
    borderRadius: "4px",
    backgroundColor: "#fff5f5",
    fontFamily: "sans-serif",
  },
  heading: {
    margin: "0 0 0.5rem",
    color: "#c0392b",
    fontSize: "1.25rem",
  },
  message: {
    margin: "0 0 1rem",
    color: "#333",
    wordBreak: "break-word",
  },
  details: {
    marginBottom: "1rem",
  },
  summary: {
    cursor: "pointer",
    color: "#666",
    fontSize: "0.875rem",
  },
  stack: {
    marginTop: "0.5rem",
    padding: "0.75rem",
    backgroundColor: "#f8f8f8",
    border: "1px solid #ddd",
    borderRadius: "3px",
    fontSize: "0.75rem",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-all",
  },
  button: {
    padding: "0.5rem 1.25rem",
    backgroundColor: "#c0392b",
    color: "#fff",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "0.9rem",
  },
};
