<parameter name="content">import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import { ErrorBoundary } from "./ErrorBoundary";

function Bomb({ shouldThrow }: { shouldThrow: boolean }) {
  if (shouldThrow) throw new Error("Test explosion");
  return <p>All good</p>;
}

// Suppress React's error boundary console output in tests
beforeEach(() => jest.spyOn(console, "error").mockImplementation(() => {}));
afterEach(() => jest.restoreAllMocks());

test("renders children when there is no error", () => {
  render(
    <ErrorBoundary>
      <Bomb shouldThrow={false} />
    </ErrorBoundary>
  );
  expect(screen.getByText("All good")).toBeInTheDocument();
});

test("shows default fallback UI on error", () => {
  render(
    <ErrorBoundary>
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  expect(screen.getByRole("alert")).toBeInTheDocument();
  expect(screen.getByText("Something went wrong")).toBeInTheDocument();
  expect(screen.getByText("Test explosion")).toBeInTheDocument();
  expect(screen.getByRole("button", { name: "Try again" })).toBeInTheDocument();
});

test("retry button resets the error state", () => {
  const { rerender } = render(
    <ErrorBoundary>
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  fireEvent.click(screen.getByRole("button", { name: "Try again" }));
  rerender(
    <ErrorBoundary>
      <Bomb shouldThrow={false} />
    </ErrorBoundary>
  );
  expect(screen.getByText("All good")).toBeInTheDocument();
});

test("calls onError with error details", () => {
  const onError = jest.fn();
  render(
    <ErrorBoundary onError={onError}>
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  expect(onError).toHaveBeenCalledWith(
    expect.objectContaining({ message: "Test explosion" }),
    expect.objectContaining({ componentStack: expect.any(String) })
  );
});

test("renders custom fallback when provided", () => {
  render(
    <ErrorBoundary fallback={(err, reset) => <button onClick={reset}>{err.message}</button>}>
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  expect(screen.getByRole("button", { name: "Test explosion" })).toBeInTheDocument();
});
</parameter>
